CREATE TABLE IF NOT EXISTS users (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,name TEXT NOT NULL,email TEXT NOT NULL,password_hash TEXT NOT NULL,role TEXT NOT NULL DEFAULT 'cashier' CHECK(role IN('admin','owner','cashier')),active BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE UNIQUE INDEX IF NOT EXISTS users_email_unique ON users(lower(email));
CREATE TABLE IF NOT EXISTS products (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,sku TEXT,barcode TEXT UNIQUE,name TEXT NOT NULL,description TEXT,category TEXT,cost_cents INTEGER NOT NULL DEFAULT 0 CHECK(cost_cents>=0),price_cents INTEGER NOT NULL CHECK(price_cents>=0),stock_quantity INTEGER NOT NULL DEFAULT 0,minimum_stock INTEGER NOT NULL DEFAULT 0 CHECK(minimum_stock>=0),active BOOLEAN NOT NULL DEFAULT TRUE,image_path TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE UNIQUE INDEX IF NOT EXISTS products_sku_unique ON products(lower(sku)) WHERE sku IS NOT NULL;
CREATE TABLE IF NOT EXISTS stock_movements (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,product_id BIGINT NOT NULL REFERENCES products(id),type TEXT NOT NULL CHECK(type IN('initial','purchase','adjustment','sale','sale_reversal')),quantity INTEGER NOT NULL,reason TEXT,user_id BIGINT REFERENCES users(id),created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS cash_sessions (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,status TEXT NOT NULL DEFAULT 'open' CHECK(status IN('open','closed')),opened_by BIGINT NOT NULL REFERENCES users(id),opened_at TIMESTAMPTZ NOT NULL DEFAULT now(),opening_amount_cents INTEGER NOT NULL DEFAULT 0 CHECK(opening_amount_cents>=0),closed_by BIGINT REFERENCES users(id),closed_at TIMESTAMPTZ,closing_notes TEXT,sales_count INTEGER NOT NULL DEFAULT 0,items_sold INTEGER NOT NULL DEFAULT 0,revenue_cents INTEGER NOT NULL DEFAULT 0,discounts_cents INTEGER NOT NULL DEFAULT 0,gross_profit_cents INTEGER NOT NULL DEFAULT 0,report_path TEXT);
CREATE UNIQUE INDEX IF NOT EXISTS idx_single_open_cash_session ON cash_sessions(status) WHERE status='open';
CREATE TABLE IF NOT EXISTS sales (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,user_id BIGINT NOT NULL REFERENCES users(id),subtotal_cents INTEGER NOT NULL CHECK(subtotal_cents>=0),discount_cents INTEGER NOT NULL DEFAULT 0 CHECK(discount_cents>=0),total_cents INTEGER NOT NULL CHECK(total_cents>=0),payment_method TEXT NOT NULL CHECK(payment_method IN('cash','pix','credit_card','debit_card','other')),amount_received_cents INTEGER,change_cents INTEGER NOT NULL DEFAULT 0 CHECK(change_cents>=0),notes TEXT,status TEXT NOT NULL DEFAULT 'completed' CHECK(status IN('completed','cancelled')),created_at TIMESTAMPTZ NOT NULL DEFAULT now(),cancelled_at TIMESTAMPTZ,cancelled_by BIGINT REFERENCES users(id),cancel_reason TEXT,cash_session_id BIGINT REFERENCES cash_sessions(id),seller_name TEXT,card_brand TEXT);
CREATE TABLE IF NOT EXISTS sale_items (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,sale_id BIGINT NOT NULL REFERENCES sales(id) ON DELETE CASCADE,product_id BIGINT NOT NULL REFERENCES products(id),product_name TEXT NOT NULL,quantity INTEGER NOT NULL CHECK(quantity>0),unit_price_cents INTEGER NOT NULL CHECK(unit_price_cents>=0),unit_cost_cents INTEGER NOT NULL DEFAULT 0 CHECK(unit_cost_cents>=0),total_cents INTEGER NOT NULL CHECK(total_cents>=0));
CREATE TABLE IF NOT EXISTS cash_backups (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,cash_session_id BIGINT NOT NULL REFERENCES cash_sessions(id) ON DELETE CASCADE,created_by BIGINT NOT NULL REFERENCES users(id),created_at TIMESTAMPTZ NOT NULL DEFAULT now(),file_name TEXT NOT NULL,record_counts JSONB NOT NULL DEFAULT '{}'::jsonb);
CREATE INDEX IF NOT EXISTS idx_cash_backups_session ON cash_backups(cash_session_id,created_at DESC);
CREATE INDEX IF NOT EXISTS idx_products_name ON products(name);CREATE INDEX IF NOT EXISTS idx_stock_movements_product ON stock_movements(product_id,created_at);CREATE INDEX IF NOT EXISTS idx_sales_created_at ON sales(created_at);CREATE INDEX IF NOT EXISTS idx_sale_items_sale ON sale_items(sale_id);
